import { readFileSync } from 'node:fs'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function parse(ref) {
  let rest = ref
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  const m = /^([^:/?#]+):/.exec(rest)
  if (m) { r.scheme = m[1]; rest = rest.slice(m[0].length) }
  const h = rest.indexOf('#')
  if (h >= 0) { r.fragment = rest.slice(h + 1); rest = rest.slice(0, h) }
  const q = rest.indexOf('?')
  if (q >= 0) { r.query = rest.slice(q + 1); rest = rest.slice(0, q) }
  if (rest.startsWith('//')) {
    const m2 = /^\/\/[^/]*/.exec(rest)
    r.authority = m2[0].slice(2)
    rest = rest.slice(m2[0].length)
  }
  r.path = rest
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const hp = a.slice(at + 1)
  const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1)
  if (colon >= 0) return { userinfo, host: hp.slice(0, colon), port: hp.slice(colon + 1) }
  return { userinfo, host: hp, port: null }
}

function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const pct = (s) =>
  s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })

function checkPct(s, name, line) {
  if (s !== null && /%(?![0-9A-Fa-f]{2})/.test(s)) {
    throw new Failure(`error: line ${line}: the ${name} has a truncated percent-encoding`)
  }
}

class Failure extends Error {}

function serialize(r, line) {
  const a = r.authority === null ? null : splitAuthority(r.authority)
  checkPct(r.path, 'path', line)
  if (a) { checkPct(a.userinfo, 'userinfo', line); checkPct(a.host, 'host', line) }
  checkPct(r.query, 'query', line)
  checkPct(r.fragment, 'fragment', line)
