  let out = ''
  if (scheme !== null) out += scheme + ':'
  let path = removeDots(pct(r.path))
  if (a) {
    let auth = ''
    if (a.userinfo !== null) auth += pct(a.userinfo) + '@'
    auth += lowerAscii(pct(a.host))
    if (a.port !== null && a.port !== '' && !(scheme !== null && DEFAULT_PORTS[scheme] === a.port)) {
      auth += ':' + pct(a.port)
    }
    out += '//' + auth
    if (path === '') path = '/'
  }
  out += path
  if (r.query !== null) out += '?' + pct(r.query)
  if (r.fragment !== null) out += '#' + pct(r.fragment)
  return out
}

function resolve(base, ref) {
  const b = parse(base)
  const r = parse(ref)
  if (r.scheme !== null) return { ...r, path: removeDots(r.path) }
  if (r.authority !== null) return { ...r, scheme: b.scheme }
  const t = { scheme: b.scheme, authority: b.authority, fragment: r.fragment }
  if (r.path === '') {
    t.path = b.path
    t.query = r.query !== null ? r.query : b.query
  } else {
    if (r.path.startsWith('/')) t.path = removeDots(r.path)
    else {
      let merged
      if (b.authority !== null && b.path === '') merged = '/' + r.path
      else {
        const i = b.path.lastIndexOf('/')
        merged = i >= 0 ? b.path.slice(0, i + 1) + r.path : r.path
      }
      t.path = removeDots(merged)
    }
    t.query = r.query
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((rec, idx) => {
      const n = idx + 1
      if (args[0] === 'normalize') return out.push(serialize(parse(rec), n))
      const sp = rec.indexOf(' ')
      if (sp < 0) throw new Failure(`error: line ${n}: expected a base and a reference`)
      const base = rec.slice(0, sp)
      if (parse(base).scheme === null) throw new Failure(`error: line ${n}: the base has no scheme`)
      out.push(serialize(resolve(base, rec.slice(sp + 1)), n))
    })
  } catch (e) {
    if (!(e instanceof Failure)) throw e
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
}

